{
  "vulnerable_symbols": [
    "jinja2.Template.render",
    "jinja2.Environment.from_string",
    "jinja2.Environment.get_template"
  ],
  "trigger": "应用把用户可控字符串作为 xmlattr 过滤器的属性键传入模板并渲染，且未过滤 /、>、= 等字符。",
  "preconditions": [
    "Jinja2 版本低于 3.1.4",
    "模板中使用了 xmlattr 过滤器",
    "用户输入被用作属性键而非仅属性值",
    "渲染结果被其他用户在 HTML 页面中查看",
    "未对属性键进行验证或过滤"
  ],
  "exploit_evidence": [
    {
      "src": 0,
      "kind": "poc",
      "quote": "A Flask web application that demonstrates a vulnerability in the Jinja2 `xmlattr` filter (payload withheld)."
    },
    {
      "src": 2,
      "kind": "poc",
      "quote": "No KEV listing yet, 7 public PoC repos."
    }
  ],
  "fixed_version": "3.1.4",
  "summary_zh": "Jinja2 xmlattr 若将用户输入作为属性键渲染可致 XSS，升级 3.1.4 并校验键。"
}
